function UIFishLevelUpNode:RefreshUI(data, parLua)
    if not data then
        return
    end

    self._curLevel = checkNumber(data.curLevel)
    self._lastLevel = checkNumber(data.lastLevel)
    self._parLua = parLua

    self:FillLevelAdditionInfo()

    self:FillUnlockPlace()

    self._co = cs_coroutine.start(function()
        if FishingUtils.IsAutoing() then
            coroutine.yield(WaitForSeconds(FishingUtils.GetAutoPageWaitTime() + 2))
            self._parLua:OnClickEventReceiverAction()
        end
    end)
end

