function UIFishLevelUpNode:FillLevelAdditionGo(go, data, ind)
    if not go or not data then
        return
    end
    CfUtils.FillText(go.transform:Find("TextTitle"), data.desc)

    local descNum = data.num
    local descNumNext = data.numNext
    if ind == 1 then
        descNum = "<size=30>LV. </size>"..data.num
        descNumNext = "<size=30>LV. </size>"..data.numNext
    end

    CfUtils.FillText(go.transform:Find("TextNow"), descNum)
    CfUtils.FillText(go.transform:Find("TextNext"), descNumNext)

    --local arrowGo = go.transform:Find("TextNext/ImgArrow")
    --if arrowGo then
    --    KTool.SetActive(arrowGo, checkBool(data.isShowArrow))
    --end
    KTool.SetActive(go, true)
end

function UIFishLevelUpNode:FillUnlockPlace()
    local level = checkNumber(self._curLevel)
    local t = FishingUtils.GetAllFishPlace()
    if not t then
        return
    end

    local vo
    for k, v in pairs(t) do
        if checkNumber(v.level) == checkNumber(level) then
            vo = v
            break
        end
    end
    if vo then
        KTool.SetActive(self.FishPoolUnlock, true)
        CfUtils.FillText(self.Text, localize("解锁")..vo.name)
    else
        KTool.SetActive(self.FishPoolUnlock, false)
    end
end

function UIFishLevelUpNode:CheckAnimatorPlayComplete()
    if not self._aniRoot then
        self._aniRoot = self.controller.gameObject.transform:Find("Container/Root"):GetComponent(typeof(Animator))
    end
    cs_coroutine.yield_return(self._aniRoot:WaitUntilAniCompleted())
end

function UIFishLevelUpNode:OnDestroy()
    if self._co then 
        cs_coroutine.stop(self._co)
        self._co = nil
    end
    
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIFishLevelUpNode
